(() => {
  const config = {
    instagram: {
      username: "hellophone.bass",
      posts: [
        {
          url: "https://www.instagram.com/reel/DdyHdR2hR6f/",
          title: "残酷な天使のテーゼ / A Cruel Angel's Thesis",
          thumb: "pic/bass-DdyHdR2hR6f.jpg",
          thumbData: "data:image/jpeg;base64,"
        },
        {
          url: "https://www.instagram.com/reel/DdyHHVChSSS/",
          title: "Neru - ロストワンの号哭",
          thumb: "pic/bass-DdyHHVChSSS.jpg",
          thumbData: "data:image/jpeg;base64,"
        },
        {
          url: "https://www.instagram.com/reel/DdQuLiahjOX/",
          title: "Ave Mujica | 顏",
          thumb: "pic/bass-DdQuLiahjOX.jpg",
          thumbData: "data:image/jpeg;base64,"
        }
      ]
    }
  };

  window.HELLOPHONE = config;

  const AVATAR_DATA = "data:image/jpeg;base64,";

  const body = document.body;
  const toggle = document.querySelector(".menu-toggle");
  const menu = document.getElementById("mobile-menu");

  const menuLabel = (open) => (open ? "Close menu" : "Open menu");

  const closeMenu = () => {
    body.classList.remove("menu-open");
    if (toggle) toggle.setAttribute("aria-expanded", "false");
    if (toggle) toggle.setAttribute("aria-label", menuLabel(false));
  };

  const openMenu = () => {
    body.classList.add("menu-open");
    if (toggle) toggle.setAttribute("aria-expanded", "true");
    if (toggle) toggle.setAttribute("aria-label", menuLabel(true));
  };

  if (toggle && menu) {
    toggle.addEventListener("click", () => {
      if (body.classList.contains("menu-open")) closeMenu();
      else openMenu();
    });

    menu.querySelectorAll("a").forEach((link) => {
      link.addEventListener("click", closeMenu);
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") closeMenu();
    });
  }

  const user = (config.instagram.username || "").replace(/^@/, "").trim();
  const profile = user ? `https://www.instagram.com/${encodeURIComponent(user)}/` : "";

  const setHref = (root, href) => {
    const link = root && (root.tagName === "A" ? root : root.querySelector("a"));
    if (link) link.href = href;
  };

  if (user) {
    document.querySelectorAll("[data-instagram-link]").forEach((el) => {
      el.hidden = false;
      setHref(el, profile);
    });
    document.querySelectorAll("[data-instagram-follow]").forEach((el) => {
      el.hidden = false;
      setHref(el, profile);
    });
  }

  const normalize = (value) => {
    if (value && typeof value === "object") {
      const parsed = normalize(value.url);
      if (!parsed) return null;
      return {
        url: parsed.url,
        title: String(value.title || "").trim(),
        thumb: String(value.thumb || parsed.thumb || "").trim(),
        thumbData: String(value.thumbData || "").trim()
      };
    }
    const match = String(value || "").trim().match(
      /(?:https?:\/\/)?(?:www\.)?(?:instagram\.com|instagr\.am)\/(p|reel|reels|tv)\/([A-Za-z0-9_-]+)/i
    );
    if (!match) return null;
    const kind = match[1].toLowerCase() === "reels" ? "reel" : match[1].toLowerCase();
    return {
      url: `https://www.instagram.com/${kind}/${match[2]}/`,
      title: "",
      thumb: ""
    };
  };

  const posts = (config.instagram.posts || []).map(normalize).filter(Boolean);
  const mount = document.querySelector("[data-instagram-posts]");
  if (!mount) return;

  const linker = document.querySelector("[data-instagram-linker]");
  if (linker) linker.remove();

  if (!document.getElementById("ig-card-style")) {
    const style = document.createElement("style");
    style.id = "ig-card-style";
    style.textContent = `
.page-lead a{color:var(--accent);text-decoration:underline;text-underline-offset:.15em}
.ig-card{border:1px solid var(--line);border-radius:var(--radius);background:var(--card);box-shadow:var(--shadow);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);overflow:hidden;min-width:0}
.ig-card-link{display:flex;flex-direction:column;height:100%;color:inherit}
.ig-card-head{display:flex;align-items:center;gap:.7rem;padding:.95rem 1.1rem .85rem}
.ig-card-avatar{width:36px;height:36px;border-radius:50%;object-fit:cover;border:1px solid var(--line)}
.ig-card-user{font-weight:500;font-size:.95rem;line-height:1.2}
.ig-card-meta{color:#8f8a83;font-size:.78rem}
.ig-card-media{position:relative;aspect-ratio:4/5;background:#141117;overflow:hidden}
.ig-card-media img,.ig-card-fallback{width:100%;height:100%;object-fit:cover;display:block}
.ig-card-fallback{background:#1a171c}
.ig-card-play{position:absolute;left:50%;top:50%;width:58px;height:58px;transform:translate(-50%,-50%);filter:drop-shadow(0 8px 16px rgba(0,0,0,.45))}
.ig-card-play circle{fill:rgba(12,11,14,.62);stroke:var(--accent);stroke-width:1.5}
.ig-card-play path{fill:var(--accent)}
.ig-card-link:hover .ig-card-play circle{fill:rgba(228,241,168,.18)}
.ig-card-body{display:flex;flex-direction:column;align-items:flex-start;gap:.85rem;padding:1rem 1.1rem 1.15rem}
.ig-card-body h2{margin:0;font-family:Syne,"Noto Sans TC",sans-serif;font-size:1.05rem;letter-spacing:-.03em;line-height:1.35;font-weight:700}
.ig-card-body .btn{pointer-events:none}
.ig-card-link:hover .btn{background:rgba(228,241,168,.12);border-color:rgba(228,241,168,.5)}
`;
    document.head.appendChild(style);
  }

  const empty = document.querySelector("[data-instagram-empty], .empty-state");
  if (empty) empty.hidden = posts.length > 0;

  const playIcon = `
    <svg class="ig-card-play" viewBox="0 0 64 64" aria-hidden="true">
      <circle cx="32" cy="32" r="31"></circle>
      <path d="M27 20.5v23L45 32 27 20.5Z"></path>
    </svg>
  `;

  posts.forEach((post) => {
    const item = document.createElement("article");
    item.className = "ig-card";
    const kind = post.url.includes("/reel/") ? "Reel" : "Post";
    const title = post.title || kind;
    const src = post.thumb || post.thumbData || "";
    const media = src
      ? `<img alt="">`
      : `<div class="ig-card-fallback"></div>`;
    item.innerHTML = `
      <a class="ig-card-link" href="${post.url}" target="_blank" rel="noopener noreferrer">
        <div class="ig-card-head">
          <img class="ig-card-avatar" alt="">
          <div>
            <div class="ig-card-user">${user || "hellophone.bass"}</div>
            <div class="ig-card-meta">${kind}</div>
          </div>
        </div>
        <div class="ig-card-media">${media}${playIcon}</div>
        <div class="ig-card-body">
          <h2>${title}</h2>
          <span class="btn">Watch on Instagram</span>
        </div>
      </a>
    `;
    const avatar = item.querySelector(".ig-card-avatar");
    if (avatar) {
      avatar.addEventListener("error", () => { avatar.src = AVATAR_DATA; }, { once: true });
      avatar.src = "pic/bass-pfp.jpg";
    }
    const img = item.querySelector(".ig-card-media img");
    if (img) {
      if (post.thumb && post.thumbData) {
        img.addEventListener("error", () => { img.src = post.thumbData; }, { once: true });
      }
      img.src = post.thumb || post.thumbData;
    }
    mount.appendChild(item);
  });

})();
